   284→            2 => GoodbyeReason::IrrelevantNetwork,
   285→            3 => GoodbyeReason::Fault,
   286→            128 => GoodbyeReason::UnableToVerifyNetwork,
   287→            129 => GoodbyeReason::TooManyPeers,
   288→            250 => GoodbyeReason::BadScore,
   289→            251 => GoodbyeReason::Banned,
   290→            252 => GoodbyeReason::BannedIP,
   291→            _ => GoodbyeReason::Unknown,
   292→        }
   293→    }
   294→}
