   675→/// The code assigned to an erroneous `RPCResponse`.
   676→#[derive(Debug, Clone, Copy, PartialEq, IntoStaticStr)]
   677→#[strum(serialize_all = "snake_case")]
   678→pub enum RpcErrorResponse {
   679→    RateLimited,
   680→    BlobsNotFoundForBlock,
   681→    InvalidRequest,
   682→    ServerError,
   683→    /// Error spec'd to indicate that a peer does not have blocks on a requested range.
   684→    ResourceUnavailable,
   685→    Unknown,
